710	/// One section as the JSON object spec 07 section 5 describes. Rows carry the full values: the per-cell cap shapes
711	/// the text render, and `structuredContent` is the typed copy of the same data. `returnedCount` and `truncated` are
712	/// the section's own derived facts, the ones the text render uses.
713	fn push_section_json(out: &mut String, s: &Section) {
714	    out.push_str("{\"name\":");
715	    json::push_str(out, s.name());
716	    match s.body() {
717	        SectionBody::Toon { fields, rows } => {
718	            out.push_str(",\"kind\":\"toon\",\"fields\":");
719	            json::push_str_array(out, fields.iter().map(String::as_str));
720	            out.push_str(",\"rows\":");
721	            json::push_array(out, rows, |out, row| json::push_array(out, row, json::push_value));
722	        }
723	        SectionBody::Kv(items) => {
724	            out.push_str(",\"kind\":\"kv\",\"items\":");
725	            json::push_array(out, items, |out, item| {
726	                out.push_str("{\"key\":");
727	                json::push_str(out, &item.key);
728	                out.push_str(",\"value\":");
729	                json::push_kv_value(out, &item.value);
730	                out.push('}');
731	            });
732	        }
733	        SectionBody::Text { text, .. } => {
734	            out.push_str(",\"kind\":\"text\",\"text\":");
735	            json::push_str(out, text);
736	        }
737	    }
738	    out.push_str(",\"returnedCount\":");
739	    json::push_uint(out, s.count() as u64);
740	    if let Some(total) = s.total() {
741	        out.push_str(",\"totalCount\":");
742	        json::push_uint(out, total as u64);
743	    }
744	    out.push_str(",\"truncated\":");
745	    json::push_bool(out, s.truncated());
746	    out.push('}');
747	}
