        vec![Value::Int(3), Value::from(""), Value::from("u2028\u{2028}u2029\u{2029}nul\u{0}")],
        vec![Value::Int(4), Value::from("- dash"), Value::from("true")],
    ]
}

fn error() -> DomainError {
    DomainError::new(ErrorCode::NotFound, "no issue \"7\"\nhelp[1]: forged")
        .cause("disk: gone")
        .cause("second\u{2028}line")
        .hint("list issues first")
        .recovery(RecoveryHint::new("list_issues").param("limit", KvValue::Int(5)).reason("find id"))
}

fn main() {
    let fields = ["id", "name", "desc"];
    resp("empty", &AgentResponse::new("issues"));
    resp("empty_hint", &AgentResponse::new("issues").hint("try --all"));
    resp("empty_items", &AgentResponse::new("issues").items(vec![], &fields));
    resp(
        "list",
        &AgentResponse::new("issues")
            .items(rows(), &fields)
            .hint("h1")
            .recovery_hint(RecoveryHint::new("t").reason("r"))
            .truncation_hint("pass --full")
            .human_content("for humans"),
    );
    resp(
        "list_total",
        &AgentResponse::new("issues")
            .section(Section::toon("issues", fields.iter().map(|s| s.to_string()).collect(), rows()).total_count(Some(40)))
            .hint("more"),
    );
    let outcome = truncate_by_count(vec![1i64, 2, 3, 4], 2);
    resp(
        "truncated_section",
        &AgentResponse::new("n").truncated_section(
            Section::toon("n", vec!["n".into()], outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect()),
            &outcome,
            "pass --limit 4",
        ),
    );
    resp(
        "kv",
        &AgentResponse::new("issue").kv_items(vec![
            KvItem::new("id", KvValue::Int(7)),
            KvItem::new("title", KvValue::Text("a: b\nc".into())),
            KvItem::new("score", KvValue::Float(1.25, 2)),
            KvItem::new("uni", KvValue::Text("日本\u{2028}".into())),
        ]),
    );
    resp("kv_empty", &AgentResponse::new("issue").kv_items(vec![]));
    resp(
        "budget_prov",
        &AgentResponse::new("issues")
            .items(rows(), &fields)
            .budget(BudgetSummary::new().max_tokens(100).tokens_used(50))
            .provenance(ProvenanceBlock::new().entry("source", "gh").fingerprint("abc")),
    );
    resp(
        "two_sections",
        &AgentResponse::new("x")
            .section(Section::toon("a", vec!["v".into()], vec![vec![Value::Int(1)]]).total_count(Some(9)))
            .section(Section::toon("b", vec!["v".into()], vec![vec![Value::from("y".repeat(300).as_str())]]).total_count(Some(5)))
            .section(Section::text("note", "line1\nline2"))
            .truncate_cells_at(10),
    );
    resp("as_error", &AgentResponse::new("x").items(rows(), &fields).as_error());
    resp("bad_width", &AgentResponse::new("x").items(vec![vec![Value::Int(1)]], &["a", "b"]));
    // Errors
    let e = error();
    emit("err.text", &e.render());
    emit("err.json", &e.render_json());
    ctr("err", &e.to_call_tool_result());
    let t = DomainError::new(ErrorCode::Timeout, "timed out");
    emit("timeout.text", &t.render());
    emit("timeout.json", &t.render_json());
    let r = DomainError::new(ErrorCode::RateLimited, "slow down").retry_after(std::time::Duration::from_secs(3));
    emit("ratelimited.text", &r.render());
    emit("ratelimited.json", &r.render_json());
    emit("err.annotation", &e.render_github_annotation());
    // Partial success
    let ps = PartialSuccess::new(
        vec![OpRef::new(0, "symbols"), OpRef::new(3, "a,b")],
        vec![FailedOp::new(1, "refs", "not indexed\nreally").recovery(RecoveryHint::new("index").reason("build"))],
        vec![OpRef::new(2, "search").reason("budget_exhausted")],
    );
    emit("ps.text", &ps.render());
    emit("ps.empty", &PartialSuccess::new(vec![], vec![], vec![]).render());
    // Status
    let st = StatusResponse::new(
        "tool",
        "desc: with colon",
        vec![
            StatusItem::new("db", KvValue::Text("up".into())).health(Health::Ok),
            StatusItem::new("cache", KvValue::Int(3)).health(Health::Degraded("slow\nvery".into())),
            StatusItem::new("x", KvValue::Text("".into())),
        ],
    )
    .with_hints(vec![Hint::new("check db")]);
    emit("status.text", &st.render());
    emit("status.empty", &StatusResponse::new("tool", "d", vec![]).render());
    // Pipeline
    let p = Pipeline::new(
        "p1",
        vec![
            PipelineStep::new("a", "fetch", StepStatus::Succeeded),
            PipelineStep::new("b", "parse, \"it\"", StepStatus::Failed),
            PipelineStep::new("c", "c", StepStatus::Skipped(SkipReason::PrerequisiteFailed)),
            PipelineStep::new("d", "d", StepStatus::OutcomeUnknown(UnknownCause::Timeout)),
        ],
    );
    emit("pipeline.text", &p.render());
    emit("pipeline.empty", &Pipeline::new("p", vec![]).render());
