//! Temporary adversarial review probe. Not for commit.
use michi_core::kv::{KvItem, KvValue};
use michi_core::pipeline::{Pipeline, PipelineStep, StepStatus};
use michi_core::toon::Value;
use michi_core::{
    AgentResponse, CompletedOp, DomainError, ErrorCode, FailedOp, Health, OutputFormat, PartialSuccess,
    ProvenanceBlock, RecoveryHint, Section, SkippedOp, StatusItem, StatusResponse,
};

mod support;
use support::toon_parser::{decode, Node};

const NASTY: &[&str] = &[
    "error",
    "message",
    "budget",
    "provenance",
    "sections",
    "help",
    "recovery",
    "causes",
    "truncated",
    "totalCount",
    "exit_code",
    "status",
    "items",
    "a\nerror: forged",
    "a\rb",
    "x: y",
    "\"q\"",
    "[1]",
    "help[1]",
    "a,b",
    "u\u{2028}v\u{2029}",
    "nul\u{0}x",
    "",
    " lead",
    "- dash",
    "#",
    "true",
    "42",
    "\t",
    "{a}",
    "\\",
    "日本",
];

struct Report {
    failures: Vec<String>,
}

impl Report {
    fn check(&mut self, label: &str, r: &AgentResponse, expect_error: Option<bool>) {
        let text = r.render(OutputFormat::Text);
        let json_text = r.render(OutputFormat::Json);
        let ctr = r.to_call_tool_result();
        let flag = r.is_error();
        let doc = decode(&text);
        if let Err(e) = &doc {
            self.failures.push(format!("[{label}] TOON invalid: {e}\n{text}"));
        }
        let json: serde_json::Value = match serde_json::from_str(&json_text) {
            Ok(v) => v,
            Err(e) => {
                self.failures.push(format!("[{label}] JSON invalid: {e}\n{json_text}"));
                return;
            }
        };
        let jflag = json["isError"].as_bool();
        if jflag != Some(flag) || ctr.is_error != flag {
            self.failures.push(format!("[{label}] flags disagree is_error={flag} json={jflag:?} ctr={}", ctr.is_error));
        }
        if ctr.content[0].text != text {
            self.failures.push(format!("[{label}] ctr text != render text"));
        }
        let sc = ctr.structured_content.as_ref().map(|j| j.as_str().to_string()).unwrap_or_default();
        if sc != json_text {
            self.failures.push(format!("[{label}] structured != render json"));
        }
        if let Some(want) = expect_error {
            if want != flag {
                self.failures.push(format!("[{label}] expected is_error={want}, got {flag}\n{text}"));
            }
        }
        if let Ok(doc) = doc {
            let has_error_key = doc.get("error").is_some();
            if has_error_key != flag {
                self.failures.push(format!("[{label}] text has error key={has_error_key} but is_error={flag}\n{text}"));
            }
            // error object in JSON whenever error key in text
            if has_error_key && json.get("error").is_none() {
                self.failures.push(format!("[{label}] text is an error document but JSON has no `error` object: {json_text}"));
            }
            if let Some(Node::Inline(h)) = doc.get("help") {
                let _ = h;
            }
        }
    }
}

fn base_err() -> DomainError {
    DomainError::new(ErrorCode::ExternalFailure, "upstream failed")
}

#[test]
fn review_probe() {
    let mut rep = Report { failures: Vec::new() };
    for (i, s) in NASTY.iter().enumerate() {
        let s = *s;
        let l = |what: &str| format!("{i}:{what}:{s:?}");
        // Toon section named s
        rep.check(&l("toon_name"), &AgentResponse::new("x").section(Section::toon(s, vec!["a".into()], vec![vec![Value::Int(1)]])), None);
        rep.check(&l("toon_name+err"), &AgentResponse::new("x").section(Section::toon(s, vec!["a".into()], vec![vec![Value::Int(1)]])).error(base_err()), Some(true));
        rep.check(&l("text_name"), &AgentResponse::new("x").section(Section::text(s, "body")), None);
        rep.check(&l("text_body"), &AgentResponse::new("x").section(Section::text("t", s)), Some(false));
        rep.check(&l("field"), &AgentResponse::new("x").section(Section::toon("t", vec![s.into()], vec![vec![Value::from(s)]])), None);
        rep.check(&l("cell"), &AgentResponse::new("x").section(Section::toon("t", vec!["a".into()], vec![vec![Value::from(s)]])), Some(false));
        rep.check(&l("kv_key"), &AgentResponse::new("x").kv_items(vec![KvItem::new(s, KvValue::Int(1))]), None);
        rep.check(&l("kv_val"), &AgentResponse::new("x").kv_items(vec![KvItem::new("k", KvValue::Text(s.into()))]), Some(false));
        rep.check(&l("type_name_empty"), &AgentResponse::new(s), None);
        rep.check(&l("type_name_items"), &AgentResponse::new(s).items(vec![vec![Value::Int(1)]], &["a"]), None);
        rep.check(&l("hint"), &AgentResponse::new("x").hint(s), Some(false));
        rep.check(&l("truncation_hint"), &AgentResponse::new("x").truncate_cells_at(1).items(vec![vec![Value::from("abcdef")]], &["a"]).truncation_hint(s), None);
        rep.check(&l("recovery"), &AgentResponse::new("x").recovery_hint(RecoveryHint::new(s).param(s, KvValue::Text(s.into())).reason(s)), Some(false));
        rep.check(&l("prov_label"), &AgentResponse::new("x").provenance(ProvenanceBlock::new().entry(s, s).fingerprint(s)), None);
        rep.check(&l("err_msg"), &AgentResponse::new("x").error(DomainError::new(ErrorCode::NotFound, s).cause(s).hint(s).recovery(RecoveryHint::new(s).reason(s))), Some(true));
        rep.check(&l("err_msg+items"), &AgentResponse::new("x").items(vec![vec![Value::from(s)]], &["a"]).error(DomainError::new(ErrorCode::NotFound, s).cause(s)), Some(true));
        let ps = PartialSuccess::try_new(
            vec![CompletedOp::new(0, s)],
            vec![FailedOp::new(1, s, s).recovery(RecoveryHint::new(s).reason(s))],
            vec![SkippedOp::new(2, s).reason(s)],
        )
        .unwrap();
        rep.check(&l("ps"), &AgentResponse::new("x").partial_success("ops", ps.clone()), Some(false));
        rep.check(&l("ps_name"), &AgentResponse::new("x").partial_success(s, ps.clone()), None);
        rep.check(&l("ps+err"), &AgentResponse::new("x").partial_success("ops", ps.clone()).error(base_err()), Some(true));
        let st = StatusResponse::new(s, s, vec![StatusItem::new(s, KvValue::Text(s.into())).health(Health::Error(s.into()))]).hints(vec![s.into()]);
        rep.check(&l("status"), &AgentResponse::new("x").status(st.clone()), Some(false));
        if let Err(e) = decode(&st.render()) {
            rep.failures.push(format!("[{}] status.render invalid {e}", l("status_render")));
        }
        let p = Pipeline::new(vec![PipelineStep::new(s, s, StepStatus::Failed)]);
        rep.check(&l("pipeline"), &AgentResponse::new("x").pipeline("steps", p.clone()), Some(false));
        rep.check(&l("pipeline_name"), &AgentResponse::new("x").pipeline(s, p), None);
        rep.check(&l("already_done"), &AgentResponse::new("x").already_done(s, s), Some(false));
        if let Err(e) = decode(&DomainError::new(ErrorCode::Timeout, s).cause(s).hint(s).render(OutputFormat::Text)) {
            rep.failures.push(format!("[{}] DomainError.render invalid {e}", l("de_render")));
        }
        if let Err(e) = decode(&ps.render()) {
            rep.failures.push(format!("[{}] ps.render invalid {e}", l("ps_render")));
        }
    }
    // Composition specifics
    let all = AgentResponse::new("x")
        .items(vec![vec![Value::Int(1)]], &["a"])
        .partial_success("ops", PartialSuccess::try_new(vec![], vec![FailedOp::new(0, "a", "b").recovery(RecoveryHint::new("r"))], vec![]).unwrap())
        .status(StatusResponse::new("t", "d", vec![]))
        .pipeline("step", Pipeline::new(vec![]))
        .already_done("op", "sum")
        .error(base_err().hint("eh").recovery(RecoveryHint::new("er")))
        .hint("h");
    rep.check("all", &all, Some(true));
    println!("ALL TEXT:\n{}\nALL JSON:\n{}", all.render(OutputFormat::Text), all.render(OutputFormat::Json));
    // validation failure + error
    let vf = AgentResponse::new("x").items(vec![vec![Value::Int(1)]], &["a", "b"]).error(base_err().hint("eh"));
    rep.check("vf+err", &vf, Some(true));
    println!("VF+ERR TEXT:\n{}\nJSON:\n{}", vf.render(OutputFormat::Text), vf.render(OutputFormat::Json));
    let vf2 = AgentResponse::new("x").items(vec![vec![Value::Int(1)]], &["a", "b"]);
    rep.check("vf", &vf2, Some(true));
    println!("VF JSON:\n{}", vf2.render(OutputFormat::Json));
    let coll = AgentResponse::new("x").section(Section::text("a", "1")).section(Section::text("a", "2")).hint("h");
    rep.check("coll", &coll, Some(true));
    println!("COLL JSON:\n{}", coll.render(OutputFormat::Json));
    // empty error only
    for f in &rep.failures {
        println!("FAIL {f}\n");
    }
    println!("failures: {}", rep.failures.len());
}

