/// Most UTF-8 bytes of string data one call may pass, summed over every string argument and nested string, and most
/// one `AgentResponse` may hold across all its calls.
///
/// This bounds the OUTPUT as well as the input. Rendering writes each string more than once, and a control character
/// is the worst case: `\u0001` is six bytes in the text, thirteen in the JSON (`\\u0001` inside the body, plus the
/// raw `sections` copy), and nineteen in `toCallToolResult` (the text plus the parsed JSON). So `n` held bytes render
/// to at most `19 * n` (see [`MAX_OUTPUT_FACTOR`]). At the old 64 MiB that was 1.2 GiB per call on Node's event loop,
/// and a response over V8's string limit (about 512 MiB) failed only after rendering it. At 16 MiB it is at most
/// 304 MiB, under that limit, so a response either renders or is rejected here, before anything is rendered.
pub(crate) const MAX_INPUT_BYTES: usize = 16 * 1024 * 1024;
/// Largest ratio of any render's output to the string bytes held (see [`MAX_INPUT_BYTES`]); a test pins it.
pub(crate) const MAX_OUTPUT_FACTOR: usize = 19;
/// V8's longest string, in characters, on 64-bit builds (`2^29 - 24`). A string longer than this cannot be handed to
/// JavaScript, so every output must stay under it.
pub(crate) const V8_MAX_STRING_LEN: usize = (1 << 29) - 24;
const _: () = assert!(MAX_INPUT_BYTES * MAX_OUTPUT_FACTOR < V8_MAX_STRING_LEN);
/// Longest single cell value, hint, reason, description or message, in UTF-8 bytes.
pub(crate) const MAX_STRING_BYTES: usize = 1024 * 1024;
/// Longest type name, field name, key, tool name, error code, truncation hint or other identifier, in UTF-8 bytes.
pub(crate) const MAX_NAME_BYTES: usize = 4 * 1024;

/// `"{what} length {len} exceeds maximum of {max}"` when `len > max`.
pub(crate) fn check_len(what: &str, len: usize, max: usize) -> napi::Result<()> {
    if len > max {
        return Err(napi::Error::from_reason(format!("{what} length {len} exceeds maximum of {max}")));
    }
    Ok(())
}

/// `"{what} byte length {len} exceeds maximum of {max}"` for a string argument napi has already copied. Used by the
/// single-string builder methods: their one argument is copied once, so the cap bounds what is kept, not the copy.

/// Bytes charged to a response's total for each section beyond its strings: roughly the size of the `Section` itself.
const SECTION_OVERHEAD: usize = 64;

/// Bytes charged for an error beyond its message and causes: the code, the struct, and the verify-first hint a
/// timeout carries.
const ERROR_OVERHEAD: usize = 256;

/// String bytes one [`JsAgentResponse`] holds, per slot. A slot that a call replaces (`truncationHint`,
/// `humanContent`, `error`) gives its old bytes back; `items`, `kvItems`, `hint`, `recoveryHint` and the outcome
/// sections (`partialSuccess`, `pipeline`, `status`, `alreadyDone`) each add a block, so they only add.
#[derive(Debug, Default)]
struct HeldBytes {
    type_name: usize,
    items: usize,
    kv_items: usize,
    hints: usize,
    recovery: usize,
    truncation_hint: usize,
    human_content: usize,
    error: usize,
    outcomes: usize,
}

impl HeldBytes {
    fn total(&self) -> usize {
        [
            self.type_name,
            self.items,
            self.kv_items,
            self.hints,
            self.recovery,
            self.truncation_hint,
            self.human_content,
            self.error,
            self.outcomes,
        ]
        .iter()
        .fold(0, |acc, n| acc.saturating_add(*n))
    }

    /// An error if replacing a slot holding `old` bytes with `new` would take the total past
    /// [`input::MAX_INPUT_BYTES`]. Changes nothing: the caller stores the new slot size once its call succeeds.
    fn check_replace(&self, old: usize, new: usize) -> napi::Result<()> {
        let total = self.total().saturating_sub(old).saturating_add(new);
        if total > input::MAX_INPUT_BYTES {
            return Err(napi::Error::from_reason(format!(
                "cumulative byte total {total} exceeds maximum of {}",
                input::MAX_INPUT_BYTES
            )));
        }
        Ok(())
    }
}

/// What one row costs beyond its cells: the row vector. `Array(100000).fill([])` has no cells and still keeps
/// 100,000 of these.
const ROW_OVERHEAD: usize = std::mem::size_of::<Vec<crate::toon::Value>>();

/// What one field name costs: its string and the `String` that holds it.
fn field_cost(f: &str) -> usize {
    std::mem::size_of::<String>().saturating_add(f.len())
}

/// What one row of a four-column outcome table (`partialSuccess`, `pipeline`, `status`) keeps beyond its strings.
const OUTCOME_ROW: usize = ROW_OVERHEAD + 4 * std::mem::size_of::<crate::toon::Value>();

/// What a named outcome section costs before its rows: its name and the section itself.
fn outcome_section_cost(name: &str) -> usize {
    field_cost(name).saturating_add(SECTION_OVERHEAD)
}

/// The sum of `costs`, saturating.
fn sum(costs: impl IntoIterator<Item = usize>) -> usize {
    costs.into_iter().fold(0, usize::saturating_add)
}

/// NAPI wrapper around [`crate::response::AgentResponse`].
///
/// Besides each call's own limits, one object holds at most 16 MiB across all its calls: caller strings (type name,
/// fields, cells, keys, hints, recovery hints, truncation hint and human content) plus the storage rows and cells
/// keep, so a table of empty rows, numbers or nulls is charged too. A call that would pass that total
/// is rejected and leaves the builder unchanged; replacing `truncationHint` or `humanContent` gives the old value's
/// bytes back first. Every `items` and `kvItems` call adds a section, so their bytes add up; each section is also
/// charged the type name's bytes plus 64, so empty calls are not free.
///

