310	/// Converts to a [`michi_core::DomainError`] whose `message` is fixed text michi wrote. What the step or the server
311	/// said (an HTTP body, a `failed()` message, a panic payload) is data that may carry secrets or instructions, so it
312	/// goes into one `causes` entry, redacted and cut to 512 bytes, never into the trusted `message`.
313	impl From<ExecutionError> for michi_core::DomainError {
314	    fn from(err: ExecutionError) -> Self {
315	        use michi_core::{DomainError, ErrorCode};
316	        match err {
317	            ExecutionError::Http { status, message, retry_after } => {
318	                let code = match status {
319	                    429 => ErrorCode::RateLimited,
320	                    502..=504 => ErrorCode::Unavailable,
321	                    _ => ErrorCode::ExternalFailure,
322	                };
323	                let retryable = michi_core::resilience::is_retryable_status(status);
324	                let mut domain_err =
325	                    with_detail(DomainError::new(code, format!("http {status}")), &message).retryable(retryable);
326	                if let Some(retry_after) = retry_after {
327	                    domain_err = domain_err.retry_after(retry_after);
328	                }
329	                domain_err
330	            }
331	            ExecutionError::Timeout { elapsed_ms } => {
332	                DomainError::new(ErrorCode::Timeout, format!("step timed out after {elapsed_ms}ms")).retryable(true)
333	            }
334	            ExecutionError::Failed { message, retryable, .. } => {
335	                with_detail(DomainError::new(ErrorCode::ExternalFailure, "the step reported an error"), &message)
336	                    .retryable(retryable)
337	            }
338	            ExecutionError::CircuitOpen { retry_after_ms } => {
339	                DomainError::new(ErrorCode::Unavailable, format!("circuit open, retry after {retry_after_ms}ms"))
340	                    .retryable(true)
341	                    .retry_after(Duration::from_millis(retry_after_ms))
342	            }
343	            ExecutionError::StepFailed { step_id, step_name, source } => {
344	                // Keeps the inner code, retryable flag, retry_after, hints and recovery; only the message gains the
345	                // step prefix.
346	                DomainError::from(*source).context(format_args!("step {step_id} ({step_name}) failed"))
347	            }
348	            ExecutionError::AmbiguousOutcome { source } => {
349	                let d = DomainError::from(*source)
350	                    .context("outcome unknown, the operation may have completed")
351	                    .retryable(false)
352	                    .retry_after(None);
353	                // A timeout that is not retryable already carries core's verify-first hint; one is enough.
354	                if d.hints().iter().any(|h| h.as_str() == michi_core::MAY_HAVE_TAKEN_EFFECT_HINT) {
355	                    d
356	                } else {
357	                    d.hint(VERIFY_BEFORE_RETRY_HINT)
358	                }
359	            }
360	            ExecutionError::Cancelled => {
361	                DomainError::new(ErrorCode::Unavailable, "step cancelled before it took effect").retryable(false)
362	            }
363	            ExecutionError::Interrupted { elapsed_ms } => DomainError::new(
364	                ErrorCode::Unavailable,
365	                format!("attempt interrupted by cancellation after {elapsed_ms}ms"),
366	            )
367	            .retryable(true),
368	            ExecutionError::Panicked { message } => {
369	                with_detail(DomainError::new(ErrorCode::ExternalFailure, "step panicked"), &message)
370	                    .retryable(false)
371	                    .hint(PANIC_HINT)
372	            }
373	            ExecutionError::DeadlinePassed { message } => {
374	                with_detail(DomainError::new(ErrorCode::Timeout, "deadline passed"), &message)
375	                    .retryable(false)
376	                    .hint(DEADLINE_HINT)
377	            }
378	        }
379	    }

