#[test]
fn redact_probe() {
    let cases = [
        r#"{"url":"https:\/\/bot:ghp_SECRETSECRETSECRET1@github.com\/o\/r"}"#,
        r#"postgres://u:p"w@host/db"#,
        "error sending request for url (https://api.x.com/v1?access_token=REDACTED,
        "https%3A%2F%2Fbot%3AREDACTED%40github.com",
        "https%3a%2f%2fbot%3aREDACTED%40github.com",
        "request failed: https://api.x.com/?token=REDACTED",
        "Authorization: Basic dXNlcjpTRUNSRVRWQUxVRQ==",
        "authorization=Basic dXNlcjpTRUNSRVRWQUxVRQ==",
        "Authorization: Bearer REDACTED",
        "Authorization: bearer REDACTED",
        "Authorization: BEARER REDACTED",
        "Authorization:Bearer\tREDACTED",
        "Bearer: REDACTED",
        "X-Api-Key: REDACTED",
        "password: REDACTED",
        r#"{"password":"REDACTED"}"#,
        "PASSWORD=REDACTED,
        "client_secret=REDACTED,
        "api-key=REDACTED,
        "x-amz-signature=REDACTED",
        "REDACTED%2F20130524",
        "access_token%3DREDACTED",
        "token = REDACTED",
        "token=\"REDACTED\"",
        "token='REDACTED'",
        "?code=SECRETOAUTHCODE&state=x",
        "session=REDACTED",
        "sessionid=REDACTED",
        "cookie: sid=REDACTED",
        "jwt=eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxIn0.SECRETSIG",
        "eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxIn0.SECRETSIG",
        "xoxb-REDACTED",
        "REDACTED",
        "REDACTED",
        "AKIAIOSFODNN7EXAMPLE",
        "glpat-REDACTEDSECRETVA",
        "REDACTED",
        "REDACTED",
        "https://user:SECRET VALUE@host",
        "REDACTED",
        "https://user:REDACTED@host",
        "https://user:SECRET`VALUE@host",
        "REDACTED",
        "git@github.com:o/r.git",
        "REDACTED",
        "REDACTED",
        "REDACTED",
        "https://u:SECRET'VALUE@host",
        "https://u:SECRET\"VALUE\"@host/path",
        "https://u:SECRET\"x/y@host",
        "npm_REDACTED",
        "xghp_REDACTED",
        "_ghp_REDACTED",
        "ghp_REDACTEDSECRET",
        "pypi-AgEIcHlwaS5vcmcREDACTED",
        "token=a&token=REDACTED",
        "token==REDACTED",
        "my.token=REDACTED,
        "Token=REDACTED",
        "TOKEN=REDACTED",
        "token=REDACTED)",
        "(token=REDACTED)",
        "token=SECRET(VALUE)",
        "token=SECRET,VALUE",
        "token=SECRET;VALUE",
        "token=REDACTED\u{2028}x",
        "token=REDACTED\u{a0}x",
    ];
    for c in cases {
        let once = redact_common_shapes(c);
        let twice = redact_common_shapes(&once);
        let leak = once.contains("SECRET") || once.contains("AKIA") || once.contains("dXNlcj");
        println!("{}{:?}\n    -> {:?}{}", if leak { "LEAK " } else { "ok   " }, c, once, if once != twice { "  NOT IDEMPOTENT" } else { "" });
    }
    // Idempotence fuzz
    let alphabet: Vec<char> = "ab:/@\"'=&?%3AF24 \\tokenpasswrdghp_Bearer[]REDACTED.-x<>`#".chars().collect();
    let mut seed: u64 = 0x1234_5678;
    let mut bad = 0;
    for _ in 0..400_000 {
        let len = (seed % 40) as usize + 1;
        let mut s = String::new();
        for _ in 0..len {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            s.push(alphabet[(seed % alphabet.len() as u64) as usize]);
        }
        let s = s.replace('t', "token=").replace('p', "https://").replace('g', "ghp_0123456789abcdefg");
        for (name, f) in [("common", redact_common_shapes as fn(&str) -> String), ("url", redact_url_userinfo)] {
            let a = f(&s);
            let b = f(&a);
            if a != b && bad < 10 {
                bad += 1;
                println!("NOT IDEMPOTENT {name}: {s:?}\n  1: {a:?}\n  2: {b:?}");
            }
        }
    }
    println!("non-idempotent found: {bad}");
}

