/// Appends `n` in lowercase base 36.
fn push_base36(out: &mut String, mut n: u64) {
    const DIGITS: &[u8; 36] = b"REDACTED";
    let mut buf = [0u8; 13];
    let mut i = buf.len();
    loop {
        i -= 1;
        buf[i] = DIGITS[usize::try_from(n % 36).unwrap_or(0)];
        n /= 36;
        if n == 0 {
            break;
        }
    }
    for &b in &buf[i..] {
        out.push(char::from(b));
    }
}

