#[test]
fn serde_equals_render_json() {
    use michi_core::kv::KvValue;
    use michi_core::toon::Value;
    use michi_core::{AgentResponse, DomainError, ErrorCode, OutputFormat, RecoveryHint, Section};
    let cases = vec![
        DomainError::new(ErrorCode::Timeout, "t"),
        DomainError::new(ErrorCode::NotFound, "a\u{2028}b\u{7f}\u{0}\"\\/").cause("c\u{2029}").hint("h\u{1}"),
        DomainError::new(ErrorCode::Conflict, "x").recovery(RecoveryHint::new("tool")),
        DomainError::new(ErrorCode::Conflict, "x").recovery(
